// Owner decision Q5 (#10743): pr-merge attests a head whose lane-armed paths
// its gate passed, and never one whose change could shrink the hold floor.
// Expected values come from the decision's conditions (both bound main-run
// lanes clean, no open thread, no hold-floor shrink against the base) and
// the security review's attack shapes, not from the code. Patches come from
// `git diff`, not from the parser under test.
import assert from "node:assert/strict";
import { Buffer } from "node:buffer";
import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { test } from "node:test";

import { astRefusal, floorChange, floorOf, jsRefusal, main, patchLines, recordOf, rowRefusal } from "./lane-armed.mjs";
import { laneArmedRecord } from "./merge-holds.mjs";
import { tempDir } from "../../../lib/test-tmp.mjs";

const REPO = "owner/repo";
const HEAD = "a".repeat(40);
const BASE = "b".repeat(40);
const MERGE_BASE = "c".repeat(40);
const RISK = "plugins/source-control/skills/babysit-prs/scripts/babysit_risk.py";
const HOLDS = ".github/scripts/pr-merge/merge-holds.mjs";
const LANE_ARMED_MJS = ".github/scripts/pr-merge/lane-armed.mjs";
// Each file's shape as the generator writes it: logic before, its floor rows
// and its LANE_ARMED and PERSON_HELD lists between the markers.
const HELD = [".github/workflows/pr-merge.yml"];
const PY = (rows, armed, held = HELD) =>
  `import re\n\n\ndef held(path):\n    return path in FLOOR\n\n\nFLOOR_CLASSES: tuple[tuple[str, str], ...] = (\n    # BEGIN floor-rows FLOOR_CLASSES\n${rows.map(([g, c]) => `    ("${g}", "${c}"),`).join("\n")}\n    # END floor-rows FLOOR_CLASSES\n)  # fmt: skip\n# BEGIN hold-floor LANE_ARM: generated by scripts/sync-hold-floor.py\nLANE_ARM_GATE = True\nLANE_ARMED: tuple[str, ...] = (\n${armed.map((g) => `    "${g}",`).join("\n")}\n)\nPERSON_HELD: tuple[str, ...] = (\n${held.map((g) => `    "${g}",`).join("\n")}\n)\n# END hold-floor LANE_ARM\nFLOOR = tuple(g for g, _ in FLOOR_CLASSES)\n\n\ndef score(x):\n    return x + 1\n`;
const MJS = (rows, armed, held = HELD) =>
  `import { posix } from "node:path";\n\nexport const HOLD_PATH_CLASSES = Object.freeze([\n  // BEGIN hold-floor HOLD_PATH_CLASSES: generated by scripts/sync-hold-floor.py\n${rows.map(([g, c]) => `  ["${g}", "${c}"],`).join("\n")}\n  // END hold-floor HOLD_PATH_CLASSES\n]);\n// BEGIN hold-floor LANE_ARM: generated by scripts/sync-hold-floor.py\nexport const LANE_ARM_GATE = true;\nexport const LANE_ARMED = Object.freeze([\n${armed.map((g) => `  "${g}",`).join("\n")}\n]);\nexport const PERSON_HELD = Object.freeze([\n${held.map((g) => `  "${g}",`).join("\n")}\n]);\n// END hold-floor LANE_ARM\nexport const HOLD_PATH_FLOOR = HOLD_PATH_CLASSES.map(([glob]) => glob);\n\nexport const score = (x) => x + 1;\n`;
// The unified diff git writes from `before` to `after`, hunks only.
function diff(before, after) {
  const dir = tempDir("lane-armed-diff-");
  writeFileSync(join(dir, "a"), before);
  writeFileSync(join(dir, "b"), after);
  const out = spawnSync("git", ["diff", "--no-index", "--no-color", "-U3", "a", "b"], { cwd: dir, encoding: "utf8" }).stdout;
  return out.slice(out.indexOf("@@")).replace(/\n$/, "");
}
const ROWS = [
  [".github/actions/request-lane-token/**", "trust"],
  [".github/scripts/pr-merge/who.mjs", "gate"],
  [".github/workflows/pr-merge.yml", "gate"],
  [".github/scripts/pr-unblock/gate-source.mjs", "enforcement"],
];
const ARMED = [".github/scripts/pr-merge/who.mjs"];
const TOKEN = ".github/actions/request-lane-token/**";

test("floorOf reads the base's rows, LANE_ARM lists and their bounds", () => {
  for (const [text, path] of [[PY(ROWS, ARMED), RISK], [MJS(ROWS, ARMED), HOLDS]]) {
    const floor = floorOf(text, path);
    assert.deepEqual([...floor.kinds], ROWS);
    assert.equal(floor.rows.end - floor.rows.begin, ROWS.length + 1, path);
  }
  assert.equal(floorOf("nothing here", RISK), null);
  // The other file's markers are not this file's.
  assert.equal(floorOf(PY(ROWS, ARMED), HOLDS), null);
});

test("floorOf refuses a base whose markers are missing, repeated or out of order, or whose region holds another line", () => {
  const good = PY(ROWS, ARMED);
  for (const [name, text] of [
    ["no BEGIN", good.replace("    # BEGIN floor-rows FLOOR_CLASSES\n", "")],
    ["no END", good.replace("    # END floor-rows FLOOR_CLASSES\n", "")],
    ["a repeated BEGIN", good.replace("    # BEGIN floor-rows FLOOR_CLASSES\n", "    # BEGIN floor-rows FLOOR_CLASSES\n    # BEGIN floor-rows FLOOR_CLASSES\n")],
    ["a repeated END", `${good}# END floor-rows FLOOR_CLASSES\n`],
    ["END before BEGIN", good.replace("# BEGIN floor-rows FLOOR_CLASSES", "# TEMP").replace("# END floor-rows FLOOR_CLASSES", "# BEGIN floor-rows FLOOR_CLASSES").replace("# TEMP", "# END floor-rows FLOOR_CLASSES")],
    ["no LANE_ARM END", good.replace("# END hold-floor LANE_ARM\n", "")],
    ["a row in an expression", good.replace(`    ("${TOKEN}", "trust"),`, `    *(("${TOKEN}", "trust"),)[:0],`)],
  ]) {
    assert.equal(floorOf(text, RISK), null, name);
  }
});

test("patchLines places each changed line against the base", () => {
  assert.deepEqual(patchLines(diff("a\nb\nc\n", "a\nx\nc\nd\n")), [
    { sign: "-", text: "b", at: 2 },
    { sign: "+", text: "x", at: 2 },
    { sign: "+", text: "d", at: 3 },
  ]);
  assert.deepEqual(patchLines("@@ -2,0 +3,1 @@\n+new"), [{ sign: "+", text: "new", at: 2 }]);
  for (const bad of [undefined, "", "diff --git a b", "@@ -1 +1 @@\n?odd"]) assert.equal(patchLines(bad), null, String(bad));
});

// Each attack the security review named, as the patch from the base's text.
const judge = (path, before, after) => floorChange(path, diff(before, after), floorOf(before, path));
test("floorChange refuses every change that could hide or drop a floor row", () => {
  const py = PY(ROWS, ARMED);
  const mjs = MJS(ROWS, ARMED);
  const kept = ROWS.filter(([glob]) => glob !== TOKEN);
  const cases = [
    // The real rows move into a docstring with a decoy marker pair; the live
    // tuple loses its markers and a trust row.
    ["a Python docstring decoy", RISK, py, `"""\n    # BEGIN floor-rows FLOOR_CLASSES\n${ROWS.map(([g, c]) => `    ("${g}", "${c}"),`).join("\n")}\n    # END floor-rows FLOOR_CLASSES\n"""\n${py.replace("    # BEGIN floor-rows FLOOR_CLASSES\n", "").replace("    # END floor-rows FLOOR_CLASSES\n", "").replace(`    ("${TOKEN}", "trust"),\n`, "")}`, /names a floor marker/],
    ["a JS block-comment decoy", HOLDS, mjs, `/*\n  // BEGIN hold-floor HOLD_PATH_CLASSES\n  ["${TOKEN}", "trust"],\n  // END hold-floor HOLD_PATH_CLASSES\n*/\n${MJS(kept, ARMED).replace("  // BEGIN hold-floor HOLD_PATH_CLASSES: generated by scripts/sync-hold-floor.py\n", "").replace("  // END hold-floor HOLD_PATH_CLASSES\n", "")}`, /names a floor marker/],
    ["a LANE_ARM decoy", HOLDS, mjs, `/*\n// BEGIN hold-floor LANE_ARM\nexport const LANE_ARMED = Object.freeze([\n]);\n// END hold-floor LANE_ARM\n*/\n${mjs.replace(`  "${ARMED[0]}",\n]);\nexport const PERSON_HELD`, `  "${ARMED[0]}",\n  ".github/workflows/pr-refine.yml",\n]);\nexport const PERSON_HELD`)}`, /names a floor marker/],
    [".slice(0, 0)", HOLDS, mjs, mjs.replace(`  [".github/workflows/pr-merge.yml", "gate"],\n`, `  ...[\n  [".github/workflows/pr-merge.yml", "gate"],\n  ].slice(0, 0),\n`), /inside the floor rows is not a row of the generated shape/],
    ["[:0]", RISK, py, py.replace(`    (".github/workflows/pr-merge.yml", "gate"),\n`, `    *((".github/workflows/pr-merge.yml", "gate"),)[:0],\n`), /removes the floor row \.github\/workflows\/pr-merge\.yml/],
    ["a removed row", RISK, py, PY(kept, ARMED), /^it removes the floor row \.github\/actions\/request-lane-token\/\*\*$/],
    ["a weakened row", HOLDS, mjs, mjs.replace(`["${TOKEN}", "trust"]`, `["${TOKEN}", "enforcement"]`), /removes the floor row/],
    ["a moved marker", RISK, py, py.replace(`    # BEGIN floor-rows FLOOR_CLASSES\n    ("${TOKEN}", "trust"),\n`, `    ("${TOKEN}", "trust"),\n    # BEGIN floor-rows FLOOR_CLASSES\n`), /names a floor marker/],
    ["a re-definition", HOLDS, mjs, `${mjs}HOLD_PATH_CLASSES = [];\n`, /^an added line of .* names HOLD_PATH_CLASSES outside the floor rows$/],
    ["a rebound derived set", RISK, py, py.replace("FLOOR = tuple(g for g, _ in FLOOR_CLASSES)", "FLOOR = ()"), /names FLOOR /],
    ["a newly lane-armed glob", HOLDS, mjs, MJS(ROWS, [...ARMED, ".github/workflows/pr-merge.yml"]), /changes the generated LANE_ARM block/],
    ["a person-held entry dropped", RISK, py, PY(ROWS, ARMED, []), /changes the generated LANE_ARM block/],
    ["a comment added inside the rows", HOLDS, mjs, mjs.replace(`  ["${TOKEN}", "trust"],\n`, `  ["${TOKEN}", "trust"],\n  // fine\n`), /not a row of the generated shape/],
    // Python folds a fullwidth identifier to ASCII (NFKC): this rebinds FLOOR_CLASSES.
    ["a fullwidth identifier", RISK, py, `${py}\uFF26\uFF2C\uFF2F\uFF2F\uFF32_CLASSES = ()\n`, /holds a non-ASCII character/],
  ];
  for (const [name, path, before, after, why] of cases) {
    assert.match(String(judge(path, before, after)), why, name);
  }
});

test("floorChange accepts a pure row addition, a person-held entry and a logic edit that names no hold", () => {
  const py = PY(ROWS, ARMED);
  const mjs = MJS(ROWS, ARMED);
  for (const [name, path, before, after] of [
    ["a row added", RISK, py, PY([...ROWS, ["docs/held/**", "gate"]], ARMED)],
    ["a row added first", HOLDS, mjs, MJS([["docs/held/**", "gate"], ...ROWS], ARMED)],
    ["a person-held entry added", HOLDS, mjs, MJS(ROWS, ARMED, [...HELD, "docs/held/**"])],
    ["a logic edit", RISK, py, py.replace("return x + 1", "return x + 2")],
    ["a method named exec", HOLDS, mjs, mjs.replace("x + 1", "/a/.exec(x)")],
  ]) {
    assert.equal(judge(path, before, after), null, name);
  }
  // lane-armed.mjs has no rows: only a hold name or marker refuses there.
  assert.equal(floorChange(LANE_ARMED_MJS, diff("const a = 1;\n", "const a = 2;\n"), null), null);
  assert.match(floorChange(LANE_ARMED_MJS, diff("const a = 1;\n", "const a = LANE_ARMED;\n"), null), /names LANE_ARMED outside/);
  // No patch (GitHub omits one for a large or binary change) refuses.
  assert.equal(floorChange(HOLDS, undefined, floorOf(mjs, HOLDS)), `${HOLDS} has no readable patch`);
  assert.equal(floorChange(HOLDS, diff(mjs, `${mjs}x\n`), null), `the base copy of ${HOLDS} cannot be read exactly`);
});

const ROW = { pr: 7, head: HEAD, ready: false, laneArmed: { paths: ARMED, lanes: { "claude-review": 0, "claude-security-review": 0 }, threads: 0, refused: null } };

test("rowRefusal passes only a clean record the gate did not refuse", () => {
  assert.equal(rowRefusal(ROW), null);
  for (const [armed, why] of [
    [{ ...ROW.laneArmed, refused: "2 review thread(s) open" }, "2 review thread(s) open"],
    [{ ...ROW.laneArmed, threads: 1 }, "the open review threads are not zero"],
    [{ ...ROW.laneArmed, threads: null }, "the open review threads are not zero"],
    [{ ...ROW.laneArmed, lanes: { "claude-review": 0, "claude-security-review": 1 } }, "a review lane has an open finding"],
    [{ ...ROW.laneArmed, lanes: { "claude-review": 0 } }, "a review lane has an open finding"],
    [{ ...ROW.laneArmed, paths: [] }, "the gate recorded no lane-armed paths"],
  ]) {
    assert.equal(rowRefusal({ ...ROW, laneArmed: armed }), why);
  }
});

test("recordOf is the countable line ci-status reads back", () => {
  const record = recordOf(ROW, "4242");
  assert.deepEqual(record, { v: 1, pr: 7, head: HEAD, paths: ARMED, lanes: { "claude-review": 0, "claude-security-review": 0 }, threads: 0, run: 4242 });
  assert.deepEqual(laneArmedRecord(`x\nlane-armed ${JSON.stringify(record)}\n`), record);
});

// A GitHub with `files` at each ref, the pull's head and base, existing check
// runs and a red ci-status job; it records every write.
// `files` maps a changed path to its head text (diffed against the merge
// base), or to a file row as GitHub lists it; `changed` is the count the pull
// reports. `moved` is the base branch tip's copy of each file, when main moved
// past the merge base.
function world({ head = HEAD, files = {}, changed, moved = {}, mergeBase = MERGE_BASE, checks = [], ciRun = { id: 9, status: "completed" }, ciJob = { id: 77, name: "ci-status", conclusion: "failure" }, fail } = {}) {
  const writes = [];
  const content = (text) => ({ encoding: "base64", content: Buffer.from(text).toString("base64") });
  const at = { [MERGE_BASE]: { [RISK]: PY(ROWS, ARMED), [HOLDS]: MJS(ROWS, ARMED) } };
  at[BASE] = { ...at[MERGE_BASE], ...moved };
  at[head] = { ...at[MERGE_BASE], ...Object.fromEntries(Object.entries(files).filter(([, after]) => typeof after === "string")) };
  const listed = [
    { filename: ".github/scripts/pr-merge/who.mjs", status: "modified", patch: "@@ -1 +1 @@\n-a\n+b" },
    ...Object.entries(files).map(([filename, after]) => (typeof after === "string" ? { filename, status: "modified", patch: diff(at[MERGE_BASE][filename], after) } : { filename, ...after })),
  ];
  const github = async (method, path, body) => {
    if (fail?.(path)) throw new Error("GET failed with status 502");
    if (method !== "GET") {
      writes.push({ method, path, body });
      return {};
    }
    if (path === `/repos/${REPO}/pulls/7`) return { head: { sha: head }, base: { sha: BASE }, changed_files: changed ?? listed.length };
    if (path === `/repos/${REPO}/compare/${BASE}...${head}`) return { merge_base_commit: { sha: mergeBase }, files: listed };
    const file = /^\/repos\/owner\/repo\/contents\/(.+)\?ref=([0-9a-f]{40})$/.exec(path);
    // A floor file the world does not hold is this checkout's copy.
    if (file) return content(at[file[2]]?.[file[1]] ?? readFileSync(new URL(`../../../${file[1]}`, import.meta.url), "utf8"));
    if (path.includes("/check-runs?check_name=pr-merge%2Flane-armed")) return { check_runs: checks };
    if (path.includes("/actions/workflows/pr-require-checks.yml/runs?head_sha=")) return { workflow_runs: ciRun ? [{ id: 3, status: "completed" }, ciRun] : [] };
    if (path === `/repos/${REPO}/actions/runs/9/jobs?per_page=100`) return { jobs: [{ id: 76, name: "lint-repo", conclusion: "success" }, ciJob] };
    throw new Error(`unexpected ${path}`);
  };
  return { github, writes };
}

async function run(rows, w, mode = "attest", extra = {}) {
  const dir = tempDir("lane-armed-");
  writeFileSync(join(dir, "summary.json"), JSON.stringify(rows));
  writeFileSync(join(dir, "output"), "");
  const lines = [];
  const log = console.log;
  console.log = (line) => lines.push(line);
  try {
    const env = { GITHUB_REPOSITORY: REPO, GITHUB_RUN_ID: "4242", SUMMARY_PATH: join(dir, "summary.json"), LANE_ARMED_OUT: join(dir, "out"), GITHUB_OUTPUT: join(dir, "output"), ...extra };
    const code = await main({ env, github: w.github, mode });
    return { code, out: lines.join("\n"), output: readFileSync(join(dir, "output"), "utf8"), dir };
  } finally {
    console.log = log;
  }
}

test("a clean lane-armed head gets the check run, its record notice, and names the artifact to upload", async () => {
  const w = world();
  const { code, out, output, dir } = await run([ROW, { pr: 8, head: "c".repeat(40), ready: true }], w);
  assert.equal(code, 0, out);
  assert.equal(w.writes.length, 1, out);
  const [post] = w.writes;
  assert.equal(post.path, `/repos/${REPO}/check-runs`);
  assert.equal(post.body.name, "pr-merge/lane-armed");
  assert.equal(post.body.head_sha, HEAD);
  assert.equal(post.body.external_id, "4242");
  assert.equal(post.body.details_url, `https://github.com/${REPO}/actions/runs/4242`);
  assert.equal(post.body.conclusion, "success");
  const record = laneArmedRecord(post.body.output.summary);
  assert.deepEqual(record, recordOf(ROW, 4242));
  assert.ok(out.includes(`::notice::lane-armed ${JSON.stringify(record)}`), out);
  assert.equal(output, `artifact=pr-merge-lane-armed-7-${HEAD}\nhead=${HEAD}\n`);
  assert.deepEqual(JSON.parse(readFileSync(join(dir, "out", "lane-armed.json"), "utf8")), record);
});

test("one head is attested a run: a later clean head waits for the next", async () => {
  const w = world();
  const second = { ...ROW, pr: 9 };
  const { code, out, output } = await run([ROW, second], w);
  assert.equal(code, 0, out);
  assert.equal(w.writes.length, 1, out);
  assert.ok(out.includes(`::notice::lane-armed refused ${JSON.stringify({ v: 1, pr: 9, head: HEAD, reason: "this run attested #7; the next run attests this head" })}`), out);
  assert.equal(output, `artifact=pr-merge-lane-armed-7-${HEAD}\nhead=${HEAD}\n`);
});

test("rerun re-runs only a finished red ci-status job of the attested head", async () => {
  const rerun = world();
  let result = await run([], rerun, "rerun", { LANE_ARMED_HEAD: HEAD });
  assert.equal(result.code, 0, result.out);
  assert.deepEqual(rerun.writes, [{ method: "POST", path: `/repos/${REPO}/actions/jobs/77/rerun`, body: undefined }]);
  for (const [w, said] of [
    [world({ ciJob: { id: 77, name: "ci-status", conclusion: "success" } }), "ci-status is not red"],
    [world({ ciRun: { id: 9, status: "in_progress" } }), "no finished ci-status run to re-run"],
    [world({ ciRun: null }), "no finished ci-status run to re-run"],
  ]) {
    result = await run([], w, "rerun", { LANE_ARMED_HEAD: HEAD });
    assert.equal(result.code, 0, result.out);
    assert.ok(result.out.includes(said), result.out);
    assert.deepEqual(w.writes, []);
  }
  result = await run([], world(), "rerun", { LANE_ARMED_HEAD: "x" });
  assert.equal(result.code, 1, result.out);
});

test("each failed condition is logged as a refusal and nothing is written", async () => {
  const refused = (pr, reason) => `::notice::lane-armed refused ${JSON.stringify({ v: 1, pr, head: HEAD, reason })}`;
  for (const [rows, w, reason] of [
    [[{ ...ROW, laneArmed: { ...ROW.laneArmed, refused: "1 review thread(s) open" } }], world(), "1 review thread(s) open"],
    [[ROW], world({ head: "d".repeat(40) }), "the head the gate judged is not the pull request's head"],
    [[ROW], world({ files: { [RISK]: PY(ROWS.slice(1), ARMED) } }), "its change could weaken the hold floor: it removes the floor row .github/actions/request-lane-token/**"],
    [[ROW], world({ files: { [HOLDS]: { status: "modified" } } }), `its change could weaken the hold floor: ${HOLDS} has no readable patch`],
    [[ROW], world({ files: { [HOLDS]: { status: "renamed", previous_filename: "x.mjs", patch: "@@ -1 +1 @@\n-a\n+b" } } }), `its change could weaken the hold floor: it renamed ${HOLDS}`],
    [[ROW], world({ changed: 5 }), "its change could weaken the hold floor: its file list is cut short"],
    [[ROW], world({ mergeBase: "unknown" }), "its change could weaken the hold floor: its merge base cannot be read"],
  ]) {
    const { code, out } = await run(rows, w);
    assert.equal(code, 0, out);
    assert.ok(out.includes(refused(7, reason)), `${reason}\n${out}`);
    assert.deepEqual(w.writes, [], reason);
  }
  const w = world({ fail: (path) => path.includes("/compare/") });
  const { code, out } = await run([ROW], w);
  assert.equal(code, 1, out);
  assert.match(out, /lane-armed refused .*a read or write failed/);
  assert.deepEqual(w.writes, []);
});

// GitHub measures the patch from the merge base. When main has since dropped
// lines above the rows, the moved tip's line numbers put a removed last row
// past END, outside the region, where its text names nothing.
test("the base copy is read at the merge base the patch is measured from", async () => {
  const mergeBase = PY(ROWS, ARMED);
  const moved = mergeBase.replace("import re\n\n\n", "");
  const last = ROWS.at(-1)[0];
  const w = world({ moved: { [RISK]: moved }, files: { [RISK]: PY(ROWS.slice(0, -1), ARMED) } });
  const { code, out } = await run([ROW], w);
  assert.equal(code, 0, out);
  assert.ok(out.includes(`its change could weaken the hold floor: it removes the floor row ${last}`), out);
  assert.deepEqual(w.writes, []);
});

// babysit_risk.py as it stands in this checkout: the base copy each
// rebinding below is added to. floor-ast.py parses both and runs neither.
const RISK_TEXT = readFileSync(new URL(`../../../${RISK}`, import.meta.url), "utf8");
const ADDED = (lines) => `${RISK_TEXT}\n\n${lines}\n`;
test("floor-ast.py refuses each reflective or aliased rebinding of the Python floor", () => {
  const cases = [
    ["locals()", 'locals()["FLOOR_" "CLASSES"] = ()', /adds a reference to locals/],
    ["an alias of globals", 'g = globals\ng()["FLOOR_" "CLASSES"] = ()', /adds a reference to globals/],
    ["globals split over lines", '(globals\n)()["FLOOR_" "CLASSES"] = ()', /adds a reference to globals/],
    ["builtins.setattr", 'import builtins\nbuiltins.setattr(object(), "x", 1)', /adds (a reference to builtins|a reference to setattr|an import)/],
    // A function's __globals__ is the module's namespace.
    ["a lambda's __globals__", '(lambda: 0).__globals__["FLOOR_" "CLASSES"] = ()', /adds a dunder name/],
    ["a frame's f_globals", 'sys._getframe().f_globals["FLOOR_" "CLASSES"] = ()', /adds a reference to (_getframe|f_globals)/],
    ["inspect.currentframe", 'inspect.currentframe().f_globals["FLOOR_" "CLASSES"] = ()', /adds a reference to (currentframe|f_globals|inspect)/],
    ["an added import", "import helper", /adds an import/],
    ["object.__setattr__", 'object.__setattr__(object(), "x", 1)', /adds a reference to __setattr__/],
    ["sys.modules __setattr__", 'sys.modules[__name__].__setattr__("FLOOR_" "CLASSES", ())', /adds (a reference to (__setattr__|modules)|a dunder name)/],
    ["__import__ exec", '__import__("builtins").exec("FLOOR_CLASSES = ()")', /adds a reference to (__import__|exec)/],
    ["importlib", 'import importlib\nimportlib.reload', /adds (a reference to importlib|an import)/],
    ["getattr", 'getattr(object(), "FLOOR_" "CLASSES")', /adds a reference to getattr/],
    ["the compile builtin", 'compile("FLOOR_CLASSES = ()", "x", "exec")', /adds a reference to compile/],
    ["__builtins__", '__builtins__["exec"]("FLOOR_CLASSES = ()")', /adds a reference to __builtins__/],
    ["a second binding", "FLOOR_CLASSES = ()", /FLOOR_CLASSES is bound 2 times/],
    ["an augmented binding", "FLOOR_CLASSES += ()", /FLOOR_CLASSES is bound 2 times/],
    ["a loop target", "for FLOOR in []:\n    pass", /FLOOR is bound 2 times/],
    ["a with target", "with open(\"x\") as HIGH_FLOOR:\n    pass", /HIGH_FLOOR is bound 2 times/],
    ["an import alias", "import os as REVIEW_FLOOR", /REVIEW_FLOOR is bound 2 times|adds an import/],
    ["a walrus", "(PERSON_HELD := ())", /PERSON_HELD is bound 2 times/],
    ["a def", "def LANE_ARMED_FLOOR():\n    return ()", /LANE_ARMED_FLOOR is bound 2 times/],
    ["an argument", "def f(FLOOR=()):\n    return FLOOR", /FLOOR is bound 2 times/],
    ["a del", "del FLOOR", /FLOOR is bound 2 times/],
    ["a global", "def f():\n    global HIGH_FLOOR", /HIGH_FLOOR is bound 2 times/],
  ];
  for (const [name, lines, why] of cases) {
    assert.match(astRefusal(RISK_TEXT, ADDED(lines)), why, name);
  }
  // A derived set re-derived, a table no longer literal, a copy that does not parse.
  assert.match(astRefusal(RISK_TEXT, RISK_TEXT.replace("FLOOR: tuple[str, ...] = tuple(g for g, _ in FLOOR_CLASSES)", "FLOOR: tuple[str, ...] = ()")), /changes how FLOOR is derived/);
  assert.match(astRefusal(RISK_TEXT, RISK_TEXT.replace("LANE_ARM_GATE = True", "LANE_ARM_GATE = bool(1)")), /LANE_ARM_GATE is not a literal/);
  assert.match(astRefusal(RISK_TEXT, `${RISK_TEXT}\ndef (\n`), /does not parse/);
});

test("floor-ast.py accepts a logic edit with no reflective name and a row addition", () => {
  assert.equal(astRefusal(RISK_TEXT, RISK_TEXT), "");
  assert.equal(astRefusal(RISK_TEXT, ADDED('def extra(x):\n    return re.compile("a").match(x) or x + 1')), "");
  // A pure logic edit inside an existing function: no new dunder, import or reflective name.
  const edited = RISK_TEXT.replace("def lane_armed(inp: RiskInput) -> bool:", "def lane_armed(inp: RiskInput) -> bool:\n    _unused = len(str(inp)) + 1");
  assert.notEqual(edited, RISK_TEXT);
  assert.equal(astRefusal(RISK_TEXT, edited), "");
  const row = '    (".github/scripts/pr-merge/lane-armed.mjs", "gate"),\n';
  assert.ok(RISK_TEXT.includes(row));
  assert.equal(astRefusal(RISK_TEXT, RISK_TEXT.replace(row, `${row}    ("docs/held/**", "gate"),\n`)), "");
});

test("a rebinding the patch rules cannot see is refused through floor-ast.py", async () => {
  const w = world({ files: { [RISK]: `${PY(ROWS, ARMED)}locals()["FLOOR_" "CLASSES"] = ()\n` } });
  const { code, out } = await run([ROW], w);
  assert.equal(code, 0, out);
  assert.ok(out.includes(`its change could weaken the hold floor: its ${RISK}: it adds a reference to locals`), out);
  assert.deepEqual(w.writes, []);
});

test("floor-ast.py is judge code: a logic edit is judged for markers and names, never read as a floor table", async () => {
  const FLOOR_AST = ".github/scripts/pr-merge/floor-ast.py";
  const source = readFileSync(new URL("./floor-ast.py", import.meta.url), "utf8");
  const logic = diff(source, source.replace('f"it adds {name}"', 'f"it now adds {name}"'));
  assert.equal(floorChange(FLOOR_AST, logic, null), null);
  assert.match(floorChange(FLOOR_AST, diff(source, source.replace('TABLES = ("FLOOR_CLASSES",', 'TABLES = (')), null), /names TABLES|names FLOOR_CLASSES/);
  const w = world({ files: { [FLOOR_AST]: { status: "modified", patch: logic } } });
  const { code, out } = await run([ROW], w);
  assert.equal(code, 0, out);
  assert.doesNotMatch(out, /cannot be read exactly/);
  assert.ok(out.includes("::notice::lane-armed {"), out);
});

test("jsRefusal refuses a JS floor file that reaches code more dynamically than its base", () => {
  const base = MJS(ROWS, ARMED);
  for (const [name, line] of [
    ["eval(", 'eval("HOLD_" + "PATH_FLOOR.length = 0");'],
    ["eval(", "eval (x);"],
    ["globalThis", 'globalThis["HOLD_" + "PATH_CLASSES"] = [];'],
    ["Function(", 'Function("return 1")();'],
    ["Reflect.", 'Reflect.set(x, "a", 1);'],
    ["Object.defineProperty", 'Object.defineProperty(x, "a", {});'],
    ["__proto__", "x.__proto__ = null;"],
    ["import(", 'await import("./x.mjs");'],
    ["require(", 'require("vm");'],
  ]) {
    assert.equal(jsRefusal(base, `${base}${line}\n`), `it adds ${name}`, name);
  }
  // As many as the base: accepted, and so is a logic edit or a method named eval.
  assert.equal(jsRefusal(`${base}eval(1);\n`, `${base}eval(2);\n`), null);
  assert.equal(jsRefusal(base, base.replace("x + 1", "x + 2")), null);
  assert.equal(jsRefusal(base, `${base}const evaluate = 1;\n`), null);
  // A floor row for another eval-* workflow is a tightening, not a call.
  assert.equal(jsRefusal(base, MJS([...ROWS, [".github/workflows/eval-foo.yml", "gate"]], ARMED)), null);
  assert.equal(judge(HOLDS, base, MJS([...ROWS, [".github/workflows/eval-foo.yml", "gate"]], ARMED)), null);
});

// lane-armed.mjs holds the very tokens it counts, as literals in its
// JS_DYNAMIC list; they are not counted, and the list cannot be edited.
test("lane-armed.mjs cannot trade a JS_DYNAMIC literal for a real call", async () => {
  const source = readFileSync(new URL("./lane-armed.mjs", import.meta.url), "utf8");
  const literal = '  ["eval(", /\\beval\\s*\\(/g],\n';
  assert.ok(source.includes(literal));
  const traded = source.replace(literal, "").replace("export function jsRefusal(baseText, headText) {", 'export function jsRefusal(baseText, headText) {\n  eval("1");');
  // The count alone sees the real call once the literal is not counted.
  assert.equal(jsRefusal(source, traded), "it adds eval(");
  // The patch rule refuses the edit inside the list before the count runs.
  const w = world({ files: { [LANE_ARMED_MJS]: { status: "modified", patch: diff(source, traded) } } });
  const { code, out } = await run([ROW], w);
  assert.equal(code, 0, out);
  assert.ok(out.includes(`its change could weaken the hold floor: a removed line of ${LANE_ARMED_MJS} is inside the JS_DYNAMIC list`), out);
  assert.deepEqual(w.writes, []);
  // Moving or dropping the block's markers refuses too.
  assert.match(floorChange(LANE_ARMED_MJS, diff(source, source.replace("  // END js-dynamic JS_DYNAMIC\n", "")), null), /names a floor marker/);
});

test("an added eval in merge-holds.mjs is refused end to end", async () => {
  const w = world({ files: { [HOLDS]: MJS(ROWS, ARMED).replace("x + 1", 'eval("x + 1")') } });
  const { code, out } = await run([ROW], w);
  assert.equal(code, 0, out);
  assert.ok(out.includes(`its change could weaken the hold floor: its ${HOLDS}: it adds eval(`), out);
  assert.deepEqual(w.writes, []);
});

// ci-status trusts only a schedule or workflow_dispatch run of pr-merge.yml on
// main (merge-holds laneArmedHold), so the job that attests runs on nothing
// else: a pull_request_target run's head_branch is the pull request's.
test("pr-merge.yml attests only from a scheduled or hand-started run on main", async () => {
  const { readFileSync } = await import("node:fs");
  const workflow = readFileSync(new URL("../../workflows/pr-merge.yml", import.meta.url), "utf8");
  const job = /\n  lane-armed:\n([\s\S]*?)(?=\n  [a-z-]+:\n)/.exec(workflow)[1];
  assert.match(job, /needs: \[merge\]/);
  assert.match(job, /&& github\.ref == 'refs\/heads\/main'\n\s+&& \(github\.event_name == 'schedule' \|\| github\.event_name == 'workflow_dispatch'\)/);
  // Post, then upload the proof, then re-run ci-status, each its own step.
  const attest = job.indexOf("run: node .base/.github/scripts/pr-merge/lane-armed.mjs attest");
  const upload = job.indexOf("name: ${{ steps.attest.outputs.artifact }}");
  const rerun = job.indexOf("run: node .base/.github/scripts/pr-merge/lane-armed.mjs rerun");
  assert.ok(attest > 0 && upload > attest && rerun > upload, job);
  assert.match(workflow, /reason: \(\.unattended\.reason \/\/ \.error\),[\s\S]*?\+ \(if \(\.unattended\.laneArmed \| type\) == "object" then \{laneArmed: \.unattended\.laneArmed\} else \{\} end\)/);
});
